8	 * Flags a city approaching the per-city capacity limit: {@code true} when {@code candidate}'s
9	 * city already holds between {@link #WARN_THRESHOLD} and {@link CityCapacity#LIMIT} - 1 owners
10	 * (inclusive), so the next one after that is rejected by {@link CityCapacity}.
11	 */
12	final class CityCapacityWarning {
13	
14	    static final int WARN_THRESHOLD = 40;
15	
16	    private CityCapacityWarning() {
17	    }
18	
19	    /**
20	     * Returns {@code true} when {@code candidate}'s city already holds at least
21	     * {@link #WARN_THRESHOLD} but fewer than {@link CityCapacity#LIMIT} of the
22	     * {@code existing} owners (city compared case-insensitively).
23	     */
24	    static boolean isApproaching(Owner candidate, Collection<Owner> existing) {
25	        long inCity = existing.stream()
26	            .filter(other -> candidate.getCity().equalsIgnoreCase(other.getCity()))
27	            .count();
28	        return inCity >= WARN_THRESHOLD && inCity < CityCapacity.LIMIT;
29	    }
30	}
